// branch tangle mirroring a state machine
match step() {
    Ok(s) if s.done => finish(),
    Ok(s) => match run(s) { Ok(v) => Ok(v), Err(e) => Err(e) },
    Err(e) => Err(e),
}

// the states as values, matched once
match step()? {
    State::Done  => finish(),
    State::Next(s) => run(s),
}
